		void DefaultManifestedValuesToOutturnButtonForAllContainers_Click(object sender, EventArgs e)
		{
			if (CurrentContainer == null || CurrentContainer.Consol == null)
			{
				Globals.Message.Show(Res.GetString("7deb9fb4-0a8f-48e6-b3b0-ac7224b7a17d", "Cannot outturn packages unless this container is attached to a consol in the Freight system"));
			}
			else
			{
				foreach (CommonContainer loopContainer in CurrentContainer.Consol.Containers)
				{
					loopContainer.DefaultOutturnFromManifested();
				}
			}
		}

