		void InitializeOutturnTabPageCustomCaptions()
		{
			if (DesignModeFinder.IsDesigning)
			{
				return;
			}

			OutturnTabPage.RunWhenBindingOrFirstShown((sender, e) =>
			{
				if (OutturnGrid == null)
				{
					return;
				}

				var customLabelMap = new PackLineCustomFieldsDescriptor().CustomFieldsInfos
					.Where(info => !string.IsNullOrEmpty(info.Caption))
					.ToDictionary(x => x.SchemaColumnName);

				if (customLabelMap.Any())
				{
					foreach (var columnInfo in OutturnGrid.ColumnStyles.OfType<ZGridColumnInfo>())
					{
						if (customLabelMap.TryGetValue(columnInfo.ColumnName, out var customLabel))
						{
							columnInfo.Caption = customLabel.Caption;
						}
					}
				}
			});
		}

